package com.example.starter.dispatch.domain;

/**
 * 调度令状态机。
 * <ul>
 *   <li>ISSUED：已下达，等待闸站签收；</li>
 *   <li>ACCEPTED：已签收，逐门执行中（执行进度以回执行体现）；</li>
 *   <li>COMPLETED：全部闸门回执收齐（终态，含个别闸门偏差告警的情形）；</li>
 *   <li>TIMEOUT：超过执行时限未收齐回执，超时升级（终态）；</li>
 *   <li>CANCELLED：签收前撤销（终态）；</li>
 *   <li>ABORTED：签收后人工中止（终态）。</li>
 * </ul>
 */
public enum OrderStatus {
    ISSUED,
    ACCEPTED,
    COMPLETED,
    TIMEOUT,
    CANCELLED,
    ABORTED;

    /** 是否终态：终态令占用的闸门释放，状态不可再变。 */
    public boolean isTerminal() {
        return this == COMPLETED || this == TIMEOUT || this == CANCELLED || this == ABORTED;
    }
}

package com.example.starter.dispatch.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 调度令中单个闸门的执行目标。
 *
 * @param gateCode       闸门编码
 * @param targetOpening  目标开度，百分比 0~100，单位 %
 */
public record GateTarget(
        @NotBlank String gateCode,
        @NotNull BigDecimal targetOpening) {
}

package com.example.starter.dispatch.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;
import java.util.List;

/**
 * 调度令下达请求。
 *
 * @param requestId 幂等键，调用方生成；同键同参返回首次结果，同键异参 409
 * @param gates     闸门目标列表，顺序即多闸门令的执行顺序
 * @param deadline  执行时限（UTC），逾期未收齐回执自动超时升级
 */
public record IssueOrderRequest(
        @NotBlank String requestId,
        @NotEmpty @Valid List<GateTarget> gates,
        @NotNull Instant deadline) {
}

