                try {
                    receiptFuture.get(10, TimeUnit.SECONDS);
                    receiptSucceeded = true;
                } catch (Exception e) {
                    receiptSucceeded = false;
                    assertThat(e.getCause()).isInstanceOf(ApiException.class);
                    assertThat(((ApiException) e.getCause()).getCode()).isEqualTo("ORDER_TIMEOUT");
                }
